import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import PaymentModal from '../components/paymentModal';
import Navbar from '../components/Navbar';
import { API_URL } from '../config';

const DOMAINS = [
  { key: 'red_team', label: 'Red Team' },
  { key: 'blue_team', label: 'Blue Team' },
  { key: 'grc', label: 'GRC' },
];
const LEVELS = [
  { key: 'beginner', label: 'Débutant' },
  { key: 'intermediate', label: 'Intermédiaire' },
  { key: 'advanced', label: 'Avancé' },
];

const Catalog = () => {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [domain, setDomain] = useState('Tous');
  const [level, setLevel] = useState('Tous');
  const [selectedCourse, setSelectedCourse] = useState(null);

  useEffect(() => {
    fetch(`${API_URL}/courses/`)
      .then(res => { if (!res.ok) throw new Error('Impossible de charger les parcours.'); return res.json(); })
      .then(data => setCourses(data))
      .catch(err => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  const filtered = courses.filter(c =>
    (domain === 'Tous' || c.domain === domain) &&
    (level === 'Tous' || c.level === level) &&
    c.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="min-h-screen text-white">
      <Navbar />
      <section className="max-w-6xl mx-auto px-6 pt-16 pb-20">
        <h1 className="text-3xl font-bold mb-2">Catalogue des parcours</h1>
        <p className="text-slate-500 text-sm mb-8">Red Team, Blue Team, GRC — trois niveaux par domaine.</p>

        <input
          type="text" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Rechercher un parcours..."
          className="w-full md:w-96 bg-slate-900/80 border border-slate-700 rounded-full px-5 py-3 text-sm text-white placeholder:text-slate-500 outline-none focus:border-blue-500 transition-colors mb-6"
        />

        <div className="flex flex-wrap gap-2 mb-4">
          <button onClick={() => setDomain('Tous')} className={`px-4 py-2 rounded-full text-xs font-semibold uppercase tracking-wide border transition-colors ${domain === 'Tous' ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-700 text-slate-400 hover:border-slate-500'}`}>Tous les domaines</button>
          {DOMAINS.map(d => (
            <button key={d.key} onClick={() => setDomain(d.key)} className={`px-4 py-2 rounded-full text-xs font-semibold uppercase tracking-wide border transition-colors ${domain === d.key ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-700 text-slate-400 hover:border-slate-500'}`}>{d.label}</button>
          ))}
        </div>

        <div className="flex flex-wrap gap-2 mb-10">
          <button onClick={() => setLevel('Tous')} className={`px-4 py-2 rounded-full text-xs font-semibold uppercase tracking-wide border transition-colors ${level === 'Tous' ? 'border-slate-500 bg-slate-800 text-white' : 'border-slate-800 text-slate-500 hover:border-slate-600'}`}>Tous les niveaux</button>
          {LEVELS.map(l => (
            <button key={l.key} onClick={() => setLevel(l.key)} className={`px-4 py-2 rounded-full text-xs font-semibold uppercase tracking-wide border transition-colors ${level === l.key ? 'border-slate-500 bg-slate-800 text-white' : 'border-slate-800 text-slate-500 hover:border-slate-600'}`}>{l.label}</button>
          ))}
        </div>

        {loading ? (
          <p className="text-slate-500 text-sm">Chargement des parcours...</p>
        ) : error ? (
          <p className="text-red-400 text-sm">{error} — vérifie que le serveur backend tourne bien sur {API_URL}.</p>
        ) : filtered.length > 0 ? (
          <div className="grid md:grid-cols-3 gap-6">
            {filtered.map(course => (
              <div key={course.id} className="group bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden hover:border-blue-500/40 hover:bg-slate-900 transition-all duration-300 shadow-xl flex flex-col">
                <div className="relative h-40 overflow-hidden">
                  <img src={course.thumbnail_url || 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=600'} alt={course.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                  {course.is_bestseller && <span className="absolute top-3 left-3 bg-amber-400 text-slate-900 text-[10px] font-bold uppercase tracking-wide px-2.5 py-1 rounded">Meilleure vente</span>}
                </div>
                <div className="p-6 flex flex-col justify-between flex-1">
                  <div>
                    <div className="flex items-center gap-2 mb-3 flex-wrap">
                      <span className="text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full bg-blue-500/10 text-blue-400">
                        {DOMAINS.find(d => d.key === course.domain)?.label || course.domain}
                      </span>
                      <span className="text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full bg-slate-800 text-slate-400">
                        {LEVELS.find(l => l.key === course.level)?.label || course.level}
                      </span>
                    </div>
                    <h3 className="text-lg font-bold mb-1 leading-snug group-hover:text-blue-400 transition-colors">{course.title}</h3>
                    {course.instructor_name && <p className="text-xs text-slate-500 mb-2">Par {course.instructor_name}</p>}
                    <p className="text-slate-400 text-sm leading-relaxed mb-6">{course.description}</p>
                  </div>
                  <div className="flex gap-3">
                    <Link to={`/course/${course.id}`} className="flex-1 text-center border border-slate-700 hover:border-slate-500 text-slate-300 hover:text-white font-semibold py-3 rounded-lg text-sm transition-colors">Détails</Link>
                    <button onClick={() => setSelectedCourse(course)} className="flex-1 bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 rounded-lg text-sm transition-colors">
                      {course.is_free ? 'Accéder' : 'Débloquer'}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="border border-dashed border-slate-800 rounded-2xl p-12 text-center text-slate-500 text-sm">Aucun parcours trouvé.</div>
        )}
      </section>
      {selectedCourse && <PaymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default Catalog;
